import{_ as s,o as i,c as a,a3 as t}from"./chunks/framework.DAK02U1-.js";const c=JSON.parse('{"title":"Releasing","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Releasing | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/dev/releasing"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/dev/releasing"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/dev/releasing"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/dev/releasing"}]]},"headers":[],"relativePath":"xclang/dev/releasing.md","filePath":"en/xclang/dev/releasing.md","lastUpdated":1792036039000}'),h={name:"xclang/dev/releasing.md"};function l(n,e,r,o,d,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="releasing" tabindex="-1">Releasing <a class="header-anchor" href="#releasing" aria-label="Permalink to &quot;Releasing&quot;">​</a></h1><p>How a release <code>&lt;llvm version&gt;.&lt;revision&gt;</code> is cut. The step list for maintainers is the release skill in <a href="https://github.com/clice-io/xclang/blob/main/.claude/skills/release/SKILL.md" target="_blank" rel="noreferrer">.claude/skills/release</a>; this page is the same process, for people. What the pipeline does is in the <a href="./release-build">build pipeline</a>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Nothing published is replaced.</strong> A rebuild, even of the same commit, is the next revision; the <code>release</code> stage refuses a version that exists.</li><li><strong>Builds run on CI</strong>, on GitHub-hosted runners, from a branch <code>exp/&lt;version&gt;</code>, not from <code>main</code>.</li><li><strong>A pending release is not mixed with pipeline changes</strong>: the release goes out with the pipeline that has been tested.</li></ul><h2 id="full-rebuild-or-repack" tabindex="-1">Full Rebuild or Repack <a class="header-anchor" href="#full-rebuild-or-repack" aria-label="Permalink to &quot;Full Rebuild or Repack&quot;">​</a></h2><p>A release whose changes are all in what the <code>package</code> stage reads from the checkout is a <strong>repack</strong>: the config files (<code>toolchain/config/</code>), the CMake package (<code>packages/cmake</code>), the Bazel module (<code>packages/bazel</code>, which the archives do not hold), the <code>xclang</code> command (<code>xclang/</code>), the license notices, the runtimes&#39; sources (<code>libc++/src</code>, from <code>toolchain/runtimes-src.ts</code>) and <code>toolchain/package.ts</code>. It reuses the compiler, runtimes, libclang and profile of the run that built the previous release, the same bytes, and takes about half an hour instead of three hours. Anything built into those, such as a patch, a pinned source, the runtimes, the CMake caches or the training, needs a full rebuild. A fix of the conda packages alone is no release, but the next conda build number of the same one.</p><h2 id="reproducible-rebuilds" tabindex="-1">Reproducible Rebuilds <a class="header-anchor" href="#reproducible-rebuilds" aria-label="Permalink to &quot;Reproducible Rebuilds&quot;">​</a></h2><p>A rebuild of a revision with its profile is meant to give every archive again, byte for byte. That is checked, not guaranteed: a bug of the compiler or linker that builds xclang can break it (<a href="./../design/roadmap#reproducible-builds">reproducible builds</a>). Every release run checks the cheap part: each host&#39;s archives made twice, and the <code>xclang</code> command built twice, on two machines each. When LLVM or the bootstrap moves, a second full build, by hand, checks the rest before the release is published:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clice-io/xclang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exp/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stages=runtimes,toolchain,asan,package,test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile-run=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ru</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repack-of=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ru</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revision=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>It builds everything but the profile again, and its <code>test</code> stage compares every host&#39;s archives with the full run&#39;s: every file must be the same, the <code>xclang</code> command and the packaging included. The release is the first run&#39;s; what differs is a bug, listed with the rebuilds checked.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Bootstrap</strong>, for a full rebuild. <code>toolchain/common.ts</code> pins the release that builds this one (<code>bootstrap-linux</code>, <code>bootstrap-macos</code>, with their sha256 from that release&#39;s <code>SHA256SUMS</code>). Move it to the previous release when that one has what the build needs.</li><li><strong>CHANGELOG.md</strong>, on the release&#39;s branch <code>exp/&lt;version&gt;</code>: Unreleased becomes the release&#39;s section, with what built it (&quot;Built by <code>&lt;bootstrap&gt;</code>.&quot;, or for a repack &quot;The compiler and runtimes are <code>&lt;previous&gt;</code>&#39;s.&quot;), and a new empty Unreleased. The tag then has it, and nothing has to follow on <code>main</code>: the docs, the READMEs and <code>examples/</code> name no release but the oldest the Bazel module takes, and reach the newest by themselves.</li><li><strong>Full run with a draft</strong>, about three hours:<div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clice-io/xclang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exp/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stages=runtimes,instrumented,train,toolchain,asan,package,test,bazel,cmake,sdk,cli,release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revision=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div>A failed stage is run again with <code>reuse-run</code> and only the stages still to do. A repack, in about half an hour:<div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clice-io/xclang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exp/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stages=package,test,bazel,cmake,sdk,cli,release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reuse-run=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ru</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile-run=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ru</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repack-of=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">previous</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revision=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><code>&lt;full run&gt;</code> is the run that built the compiler. Its toolchain and runtimes artifacts last 14 days, its profile 30; after that, only a full rebuild can make a release. With <code>repack-of</code>, the <code>test</code> stage checks each host&#39;s archives against that release&#39;s, file by file (<code>tests/release/repack.ts</code>): only the packaging&#39;s files may differ. When LLVM or the bootstrap moved, the second full build of <a href="#reproducible-rebuilds">reproducible rebuilds</a> runs next to it.</li><li><strong>Check the draft</strong>: 17 assets, every job of the run green, sizes against the previous release. Its commit is <code>bazel: the module of &lt;version&gt;</code>, which the <code>release</code> stage commits on the run&#39;s, with its times, and pushes to the branch: <code>packages/bazel/bazel/versions.bzl</code> and <code>MODULE.bazel</code> name the release and its digests, so its tag, and <code>main</code> after it, download its archives through <code>git_override</code>. The commit also merges the <code>latest</code> branch, keeping its own files: <code>main</code> takes the release&#39;s branch squashed, and without the merge the tag would not descend from the one before, which <code>latest</code> must move forward from. The first parent is the run&#39;s commit. checks.yml fails while the module names an older release than the latest. A draft that is deleted leaves that commit on the branch, naming a release that does not exist: the branch goes back to its first parent before another run.</li><li><strong>Notes</strong>: what it was built by, then what changed for users, from the release&#39;s section of CHANGELOG.md. A repack&#39;s say that the compiler and runtimes are the previous release&#39;s, the same bytes.</li><li><strong>Publish</strong>, which creates the tag, and then merge the release&#39;s branch into <code>main</code> with a pull request (squashed, as every change to <code>main</code>), which brings its CHANGELOG section and the module of the release. Publishing starts published.yml: the Bazel module tested with the published archives and published to bazel.clice.io, <code>tests/cmake</code> built from the tag as a user&#39;s FetchContent does, the conda packages made, tested and published, the <code>latest</code> branch moved to the tag, and examples.yml, the docs&#39; commands against the release on every host. A packaging fix of the conda packages alone is conda.yml by hand, with the next build number.</li><li><strong>bench.yml</strong> with the release run&#39;s artifacts, when performance matters for the notes or the docs.</li></ol>`,12)])])}const g=s(h,[["render",l]]);export{c as __pageData,g as default};
